            {\rhd {\mathopen {}\left (A \multimap  B\right )\mathclose {}} \;\vdash \; A \multimap  B}\;{\mathopen {}\left (\multimap \right )\mathclose {}}
    }{\top  \;\vdash \; A \multimap  B}\;{\mathopen {}\left (\mathrm {L\ddot  ob}\right )\mathclose {}}
  }{I \;\vdash \; A \multimap  B}\;{\mathopen {}\left (I \vdash  \top \right )\mathclose {}}
}{A \;\vdash \; B}\;{\mathopen {}\left (\multimap ,\ A \otimes  I \cong  A\right )\mathclose {}}

